var s={en:`Building access controllers must preserve safe emergency exits during WAN outages. Cloud-managed rules are convenient but physical safety is critical.`,ua:`Контролери доступу до будівлі мають підтримувати безпечні аварійні виходи при відключенні WAN. Хмарні правила зручні, але фізична безпека важливіша.`};var i={en:[`Compare cloud-controlled, edge-controlled and hybrid models.`,`Draw offline safety decisions and verified policy updates.`,`Write ADR with failure modes, testing and compliance assumptions.`],ua:[`Порівняй хмарну, локальну й гібридну модель.`,`Намалюй офлайн-рішення безпеки й перевірку політик.`,`Напиши ADR про відмови, тести й нормативні припущення.`]};var t=[{en:`Critical physical safety does not require a live cloud request.`,ua:`Критична фізична безпека не залежить від активного запиту до хмари.`},{en:`Remote updates are authenticated, auditable and recoverable.`,ua:`Віддалені зміни авторизовані, аудитовані й відновлювані.`}];var n={scenario:s,tasks:i,checks:t};export{t as checks,n as default,s as scenario,i as tasks};